def median(xs):
    if not xs:
        raise ValueError("median() arg is an empty sequence")
    ordered = sorted(xs)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2
